'Linear Graphs':d=>{let m=pk([[1,2],[2,3],[3,2],[3,1],[2,1],[1,3],[4,3],[5,2]]),s=r(0,1)?1:-1,x1=r(-3,2),dx=r(1,3),y1=r(-3,3),x2=x1+dx*m[1],y2=y1+s*dx*m[0];return mc(`A straight line passes through the points (${x1}, ${y1}) and (${x2}, ${y2}). What is its gradient?`,fa(s*m[0],m[1]),[fa(-s*m[0],m[1]),fa(s*m[1],m[0]),fa(-s*m[1],m[0]),fa(s*m[0]+1,m[1])])},
