'Linear Relationships':d=>{let a=r(2,6),b=r(1,9),x0=r(1,4),s=r(1,3),xs=[x0,x0+s,x0+2*s],f=x=>a*x+b,tb=dt(['x',...xs],[['y',...xs.map(f)]]);if(r(0,1)){let x=x0+3*s;return mc(`The values of y follow a rule based on x.${tb}What is y when x is ${x}?`,f(x),[...nw(f(x)),f(x)+a])}return mc(`The values of y follow a rule based on x.${tb}Which rule gives y from x?`,`y = ${a}x + ${b}`,[`y = ${b}x + ${a}`,`y = ${a}x + ${b+1}`,`y = ${a+1}x + ${b}`,`y = ${a}x − ${b}`])},
'Food Chains':d=>{let c=pk(FWC),k=r(0,3),e=c.map((o,i)=>i<k?((k-i)%2?1:-1):-1),ix=[0,1,2,3].filter(i=>i!=k),str=v=>ix.map(i=>`${v[i]>0?'more':'fewer'} ${c[i]}`).join(', '),cand=[];for(let m=1;m<8;m++){let v=[...e],c2=0;ix.forEach((i,j)=>{if(m>>j&1){v[i]=-v[i];c2++}});cand.push(str(v))}return mc(`In a food chain, ${c[0]} are eaten by ${c[1]}, ${c[1]} are eaten by ${c[2]}, and ${c[2]} are eaten by ${c[3]}. A disease kills most of the ${c[k]}. Which is the most likely short-term result for the other organisms?`,str(e),cand)},
