const WP=[...ADDWP,[4,'Write about a time you changed your mind.'],[4,'Describe a place that feels magical to you.'],[6,'"Failure is a better teacher than success." Discuss.'],[6,'Write a story that begins with a locked door.'],[8,'Should schools abolish homework? Argue your view.'],[8,'Describe a moment of silence and what it revealed.'],[9,'"Progress always comes at a cost." Discuss.'],[9,'Write a story in which the narrator cannot be trusted.']];
const PIC=[['pic1.svg','A suitcase left on a bench on an empty station platform at dusk'],['pic2.svg','A ladder leaning against a wall beneath a lit window at night'],['pic3.svg','A small rowing boat tied to the end of a long jetty in mist']];
const NP=[[6,'You are a keeper at a remote weather station. A storm cuts the radio and you are alone for days. Write a complete narrative that conveys the drama of what happened.',['Log, day one: Wind steady from the south-west. Everything normal, almost too normal.','Note on the fridge: “Supply boat due Friday. Do NOT climb the mast in a gale.”','A photograph: a single set of footprints leading away from the hut across bare rock.']],[7,'You are the first to arrive at your school the morning after a flood. Write a complete narrative that conveys the drama of what you find.',['Voicemail left at 2 am: “Don’t go in on your own. Wait for—” (the message cuts off)','A photograph: chairs stacked on desks, a muddy line halfway up the wall.','A sticky note on the principal’s door: “Back at 9. Don’t panic.”']],[5,'You discover a door at the back of the school library that no one else seems to notice. Write a complete narrative that conveys the drama of what happens next.',['A library card stamped with a date forty years ago.','A note in the margin of a book: “Don’t open it twice.”','The sound of a clock ticking behind the shelves.']]];
const PP=[[6,'Write a persuasive piece arguing whether or not homework should be banned in primary schools. Use the stimulus and your own ideas.',['Practice stimulus (invented): Year 6 students at one school averaged three hours of homework a week.','A parent writes: “By the time we finish the worksheet, nobody has the energy to read together.”','A teacher writes: “Practice at home is how skills become automatic.”']],[7,'Write a persuasive piece arguing whether or not zoos should be closed. Use the stimulus and your own ideas.',['Practice stimulus (invented): A city zoo has 400 animals and 900,000 visitors a year.','A visitor writes: “I only learned to care about rhinos because I saw one up close.”','A campaigner writes: “No enclosure is a substitute for a home range of hundreds of kilometres.”']],[5,'Write a persuasive piece arguing whether or not sport should be compulsory at school. Use the stimulus and your own ideas.',['Practice stimulus (invented): Students at one school spend about 90 minutes a week in sport lessons.','A student writes: “I hate team sports, but I loved the bushwalk we did.”','A coach writes: “Habits formed at twelve often last a lifetime.”']]];
const WC=[['Ideas (what you have to say)',['My idea is not the first thing everyone would write','I gave specific details, feelings or events, not only general claims','There is a clear story or a clear point of view']],['Organisation',['I planned before I started writing','The opening, middle and ending are clear and fit together','Each paragraph has one job']],['Expression',['My sentences vary in length and in how they begin','I chose precise words over impressive ones','I proofread spelling and punctuation']]];
const WCS=[WC,[['Complete narrative',['It has a clear beginning, a problem and an ending','The ending resolves the problem or answers it on purpose']],['Using the prompt',['I used the prompt material and added my own ideas','The drama of the situation comes through']],['Engagement',['I showed feelings and details instead of only listing events','The opening grabs the reader']],['Expression',['Varied sentences and precise words','Accurate punctuation and paragraphs','I proofread']]],[['Contention and arguments',['My position is clear from the start','Each argument has a reason or an example','I used the stimulus and my own ideas']],['Persuasive strategies',['I used at least two techniques (rhetorical question, emotive language, evidence, repetition)','I answered the other side']],['Structure',['Introduction, developed arguments and a firm conclusion','One main point per paragraph']],['Expression',['Varied sentences and a confident tone','Accurate punctuation','I proofread']]]];
const WTN=['ACER Written Expression (25 min)','Creative narrative (5 + 30 min)','Persuasive writing (5 + 30 min)'];
let Wp='',Wy=6,Wi=PIC[0],Wk=0,Ws=[];
function writeView(y,k){let kk=k!=null?k:((LS('sp_draft')||{}).k||0);if(kk&&!isPro())return paywall('The creative narrative and persuasive writing tasks');nav('write');let d=LS('sp_draft')||{};Wy=y||d.y||6;Wk=k!=null?k:(d.k||0);let fresh=!(d.p&&d.k==Wk&&!y);
if(fresh){let B=[WP,NP,PP][Wk],c=B.filter(p=>Math.abs(p[0]-Wy)<=2),x=pk(c.length?c:B);Wp=x[1];Ws=x[2]||[];Wi=pk(PIC);d={}}else{Wp=d.p;Ws=d.s||[];Wi=PIC.find(x=>x[0]==d.i)||PIC[0]}
let pic=`<img src="${Wi[0]}" alt="${esc(Wi[1])}" style="width:100%;height:auto">`,body=Wk==0?`<h3>Two separate ${Wy<=6?20:25}-minute tests</h3><p class=m>In the practice papers these are two different sittings. Do one now and the other after a break.</p><div class=g><div class=c style="margin:0"><b>Test 1: words</b><p style="font-size:1.1rem">${esc(Wp)}</p></div><div class=c style="margin:0"><b>Test 2: picture</b><p>Use this picture as the starting point. Write about something that happened or might have happened.</p>${pic}</div></div>`:`<h3>Your task</h3><p style="font-size:1.1rem">${esc(Wp)}</p><h3>Prompt material</h3><ul>${Ws.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${Wk==1?pic:''}<p class=m>You have 5 minutes to plan, which is not assessed, and 30 minutes to write.</p>`;
$('#app').innerHTML=`<div class=c><h2>Writing practice</h2><p class=m>${Wk==0?(Wy<=6?'ACER writing for Years 4 to 6 has two extended responses in different genres, 20 minutes each (40 minutes in total). They are assessed on the quality of content and ideas and the structure of expression.':'ACER Written Expression has two tests (Test 1 and Test 4) of 25 minutes each, with two topics set so you can use different styles of writing. It focuses on how well you express your thoughts and ideas. Writing that looks rehearsed rather than developed from the prompt is penalised.'):'This format gives 5 minutes to plan and 30 minutes to write, using the prompt material and your own ideas.'}</p><div class=g><label>Task<select onchange="wnew(Wy,+this.value)">${WTN.map((n,i)=>`<option value=${i}${i==Wk?' selected':''}>${i==0?(Wy<=6?'ACER Writing (20 min each)':'ACER Written Expression (25 min each)'):n}${i&&!isPro()?' (Pro)':''}`).join('')}</select></label><label>Year level<select onchange="wnew(+this.value,Wk)">${[4,5,6,7,8,9,10,11,12].map(n=>`<option value=${n}${n==Wy?' selected':''}>Year ${n}`).join('')}</select></label></div>${body}<p><button onclick="wnew(Wy,Wk)">New task</button> <button onclick=wtimer()>Start ${Wk?'5 + 30':(Wy<=6?'20':'25')} minute timer</button></p><div id=wt style="font-weight:700"></div><h3>1. ${Wk==2?'Plan: contention, arguments and persuasive strategies':'Plan'}</h3><textarea id=wpl rows=4 style="width:100%" oninput=wsave()>${esc(d.pl||'')}</textarea><h3>2. Write${Wk?'':' and edit'}</h3><textarea id=wtx rows=14 style="width:100%" oninput=wsave()>${esc(d.tx||'')}</textarea><p class=m id=wc></p><button class=p onclick=wcheck()>Finish and self-check</button><div id=wres></div></div>`;wsave()}
function wnew(y,k){try{localStorage.removeItem('sp_draft')}catch(e){}writeView(y,k)}
function wsave(){let t=$('#wtx').value;try{SV('sp_draft',{p:Wp,i:Wi[0],y:Wy,k:Wk,s:Ws,pl:$('#wpl').value,tx:t})}catch(e){}$('#wc').textContent=t.trim().split(/\s+/).filter(Boolean).length+' words. Your draft is saved in this browser only.'}
function wtimer(){clearInterval(window.wi);let ph=Wk?[['Planning',300],['Writing',1800]]:[['Writing',Wy<=6?1200:1500]],i=0,e=Date.now()+ph[0][1]*1000;window.wi=setInterval(()=>{if(!$('#wt'))return clearInterval(window.wi);let s=Math.max(0,Math.round((e-Date.now())/1000));$('#wt').textContent=ph[i][0]+': '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(!s){if(ph[i+1]){i++;e=Date.now()+ph[i][1]*1000}else clearInterval(window.wi)}},500)}
function wcheck(){let n=$('#wtx').value.trim().split(/\s+/).filter(Boolean).length;$('#wres').innerHTML=`<h3>3. Self-check, honestly</h3>${WCS[Wk].map((g,i)=>`<b>${g[0]}</b>${g[1].map(c=>`<label><input type=checkbox class=wk data-g=${i}>${c}</label>`).join('')}`).join('')}<br><button class=p onclick=wscore(${n})>Score it</button><p id=wv></p>`}
function wscore(n){let gs=WCS[Wk],k=gs.map((g,i)=>document.querySelectorAll('.wk[data-g="'+i+'"]:checked').length),T=gs.reduce((a,g)=>a+g[1].length,0),t=k.reduce((a,b)=>a+b,0),w=0,m=2;gs.forEach((g,i)=>{let q=k[i]/g[1].length;if(q<m){m=q;w=i}});$('#wv').innerHTML=`<b>${t} of ${T} ticked, ${n} words.</b> `+gs.map((g,i)=>g[0].split(' (')[0]+' '+k[i]+'/'+g[1].length).join(', ')+'. '+(n<120?'That is too short to be a serious attempt. ':'')+(t/T<.45?'This is not exam standard yet. Several basics are missing and they cost marks every time. ':t/T<.8?'Partway there. ':'Solid structure. ')+`Your weakest area is ${gs[w][0].split(' (')[0].toLowerCase()}. ScholarEdge cannot mark writing, so ask a teacher or tutor to read it.`}
